def restock(cart, name, qty):
    new_cart = [row[:] for row in cart]
    for row in new_cart:
        if row[0] == name:
            row[1] = row[1] + qty
            return new_cart
    new_cart.append([name, qty])
    return new_cart

def invert(d):
    result = {}
    for name, mark in d.items():
        result.setdefault(mark, []).append(name)
    return result

