class TemporaryError(Exception):
    pass


def run(mode):
    try:
        if mode == "temp":
            raise TemporaryError("temporary")
        if mode == "value":
            raise ValueError("bad value")
    except TemporaryError:
        print("retry")
        raise
    except ValueError:
        print("invalid")
    else:
        print("ok")
    finally:
        print("cleanup")


try:
    run("temp")
except TemporaryError:
    print("stop")
